import * as React from "react";

import { cn, titleIfClamped } from "../lib/utils";
import { Breadcrumb, type BreadcrumbCrumb } from "./breadcrumb";
import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from "./dropdown-menu";
import { Icon, type IconSource } from "./icon";

import styles from "./page-header.module.css";

export type PageHeaderMoreAction = {
  label: string;
  icon?: IconSource;
  /** Navigates instead of acting in place: renders a link, as a button and as a menu item. */
  href?: string;
  onSelect?: () => void;
  variant?: "default" | "destructive";
  disabledReason?: string;
};

/** The org, sub-org or other scope the page belongs to, shown on one line above the title. */
export type PageHeaderScope = {
  label: string;
  icon?: IconSource;
};

export type PageHeaderProps = Omit<React.ComponentPropsWithoutRef<"header">, "title"> & {
  title: React.ReactNode;
  size?: "lg" | "md";
  mono?: boolean;
  breadcrumb?: readonly BreadcrumbCrumb[];
  maxItems?: number;
  /** Truncates before the title does, with the full label on hover. */
  scope?: PageHeaderScope;
  /** Right after the title: status badges, and the page's DocumentationLink so it stays paired with the title. */
  badges?: React.ReactNode;
  description?: React.ReactNode;
  actions?: React.ReactNode;
  /**
   * Secondary actions, drawn as outline buttons before `actions` while the header is wide. Below the
   * narrow breakpoint they move into a "More actions" menu to leave more room for the title.
   * Existing `actions` keep their usual responsive behavior.
   */
  moreActions?: readonly PageHeaderMoreAction[];
  moreLabel?: string;
  tabs?: React.ReactNode;
  /** Leading logo or icon. On a narrow header it drops when the title would otherwise be cut. */
  media?: React.ReactNode;
  /** Keeps a long title on one line, ending in an ellipsis with the full title on hover, instead of wrapping. */
  truncateTitle?: boolean;
};

export function PageHeader({
  title,
  size = "lg",
  mono = false,
  breadcrumb,
  maxItems,
  scope,
  badges,
  description,
  actions,
  moreActions,
  moreLabel = "More actions",
  tabs,
  media,
  truncateTitle = false,
  className,
  ref,
  ...props
}: PageHeaderProps & { ref?: React.Ref<HTMLElement> }) {
  const titleRef = React.useRef<HTMLHeadingElement>(null);
  const mediaRef = React.useRef<HTMLSpanElement>(null);
  const hasMedia = Boolean(media);
  const [titleClamped, setTitleClamped] = React.useState(false);
  const [titleExpanded, setTitleExpanded] = React.useState(false);
  React.useEffect(() => {
    const element = titleRef.current;
    if (!element || (truncateTitle && !hasMedia)) return;
    const titleCuts = () => {
      const style = getComputedStyle(element);
      if (style.getPropertyValue("--cipher-page-header-title-clamp").trim() !== "2") return false;
      if (truncateTitle) return element.scrollWidth > element.clientWidth;
      const lines =
        style.display === "inline"
          ? element.getClientRects().length
          : element.scrollHeight / parseFloat(style.lineHeight);
      return lines > 2.5;
    };
    const measure = () => {
      const mediaElement = mediaRef.current;
      if (mediaElement) {
        delete mediaElement.dataset.dropped;
        if (titleCuts()) mediaElement.dataset.dropped = "";
      }
      if (truncateTitle) return;
      const clamps = titleCuts();
      setTitleClamped(clamps);
      if (clamps) element.title = element.textContent ?? "";
      else {
        element.removeAttribute("title");
        setTitleExpanded(false);
      }
    };
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    if (element.parentElement) observer.observe(element.parentElement);
    const mutations = new MutationObserver(measure);
    mutations.observe(element, { subtree: true, childList: true, characterData: true });
    document.fonts.addEventListener("loadingdone", measure);
    return () => {
      observer.disconnect();
      mutations.disconnect();
      document.fonts.removeEventListener("loadingdone", measure);
    };
  }, [truncateTitle, hasMedia]);
  const titleToggle = !truncateTitle && titleClamped;
  const more = moreActions && moreActions.length > 0 ? moreActions : null;
  const moreTriggerRef = React.useRef<HTMLButtonElement>(null);
  const [moreOpen, setMoreOpen] = React.useState(false);
  React.useEffect(() => {
    const trigger = moreTriggerRef.current;
    if (!moreOpen || !trigger) return;
    const observer = new ResizeObserver(() => {
      if (!trigger.getClientRects().length) setMoreOpen(false);
    });
    observer.observe(trigger);
    return () => observer.disconnect();
  }, [moreOpen]);
  return (
    <header
      ref={ref}
      data-slot="page-header"
      data-size={size}
      className={cn(styles.header, className)}
      {...props}
    >
      {breadcrumb && breadcrumb.length > 0 && (
        <Breadcrumb
          aria-label="Page path"
          items={breadcrumb.map((crumb, index) =>
            index === 0
              ? {
                  ...crumb,
                  media: crumb.media ?? <Icon name="chev-left" size={14} />
                }
              : crumb
          )}
          maxItems={maxItems}
          lastIsCurrent={false}
          className={styles.trail}
        />
      )}
      <div className={styles.main}>
        {media && (
          <span ref={mediaRef} data-slot="page-header-media" className={styles.media}>
            {media}
          </span>
        )}
        {scope && (
          <div data-slot="page-header-scope" className={styles.scope}>
            {scope.icon && <Icon icon={scope.icon} size={14} />}
            <span
              className={styles.scopeLabel}
              onPointerEnter={(event) => titleIfClamped(event.currentTarget)}
            >
              {scope.label}
            </span>
          </div>
        )}
        <div
          className={styles.titleLine}
          data-flow={truncateTitle || (titleClamped && !titleExpanded) ? undefined : "inline"}
        >
          <h1
            ref={titleRef}
            data-truncate={truncateTitle || undefined}
            data-expanded={titleExpanded || undefined}
            data-clamped={titleClamped || undefined}
            className={cn(styles.title, mono && styles.mono)}
            onPointerEnter={
              truncateTitle ? (event) => titleIfClamped(event.currentTarget) : undefined
            }
          >
            {titleToggle ? (
              <span
                role="button"
                tabIndex={0}
                aria-expanded={titleExpanded}
                className={styles.titleToggle}
                onClick={() => {
                  if (window.getSelection()?.isCollapsed !== false)
                    setTitleExpanded(!titleExpanded);
                }}
                onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  setTitleExpanded(!titleExpanded);
                }}
              >
                {title}
              </span>
            ) : (
              title
            )}
          </h1>
          {badges && <span className={styles.titleGap}> </span>}
          {badges && (
            <span data-slot="page-header-badges" className={styles.badges}>
              {badges}
            </span>
          )}
        </div>
        {(actions || more) && (
          <div
            data-slot="page-header-actions"
            className={styles.actions}
            onPointerOver={(event) => {
              const button =
                event.target instanceof Element
                  ? event.target.closest<HTMLElement>("[data-slot=button]")
                  : null;
              const text = button?.querySelector<HTMLElement>("[data-slot=button-text]");
              if (!button || !text) return;
              const generated = button.dataset.autoTitle;
              if (generated !== undefined && button.title !== generated) {
                delete button.dataset.autoTitle;
                return;
              }
              if (button.title && generated === undefined) return;
              if (getComputedStyle(text).position === "absolute") {
                const label = text.textContent ?? "";
                button.title = label;
                button.dataset.autoTitle = label;
              } else if (generated !== undefined) {
                button.removeAttribute("title");
                delete button.dataset.autoTitle;
              }
            }}
          >
            {more && (
              <>
                <span data-slot="page-header-more-inline" className={styles.moreInline}>
                  {more.map((action) => (
                    <Button
                      key={action.label}
                      variant="outline"
                      icon={action.icon}
                      disabledReason={action.disabledReason}
                      asChild={Boolean(action.href)}
                      onClick={action.href ? undefined : action.onSelect}
                    >
                      {action.href ? <a href={action.href}>{action.label}</a> : action.label}
                    </Button>
                  ))}
                </span>
                <DropdownMenu open={moreOpen} onOpenChange={setMoreOpen}>
                  <DropdownMenuTrigger ref={moreTriggerRef} asChild>
                    <Button variant="outline" icon="more" iconOnly className={styles.moreMenu}>
                      {moreLabel}
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="start">
                    {more.map((action) => (
                      <DropdownMenuItem
                        key={action.label}
                        variant={action.variant}
                        disabledReason={action.disabledReason}
                        asChild={Boolean(action.href)}
                        onSelect={action.href ? undefined : action.onSelect}
                      >
                        {action.href ? <a href={action.href}>{action.label}</a> : action.label}
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            )}
            {actions}
          </div>
        )}
        {description && (
          <div data-slot="page-header-description" className={styles.description}>
            {description}
          </div>
        )}
      </div>
      {tabs && <div className={styles.tabs}>{tabs}</div>}
    </header>
  );
}
PageHeader.displayName = "PageHeader";

.header {
  container: page-header / inline-size;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.trail {
  margin-bottom: var(--cipher-space-8);
}
.trail [data-slot="breadcrumb-name"] {
  color: var(--cipher-muted);
  transition: color var(--cipher-duration-fast) var(--cipher-ease-standard);
}
.trail [data-slot="breadcrumb-name"]:hover {
  color: var(--cipher-ink);
}
.main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "title actions"
    "description description";
  align-items: start;
  column-gap: var(--cipher-space-24);
  min-width: 0;
}
.main:has(> .media:not([data-dropped])) {
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "media title actions"
    "media description description";
}
.main:has(> .scope) {
  grid-template-areas:
    "scope ."
    "title actions"
    "description description";
}
.main:has(> .media:not([data-dropped])):has(> .scope) {
  grid-template-areas:
    "media scope ."
    "media title actions"
    "media description description";
}
.scope {
  grid-area: scope;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  margin-bottom: var(--cipher-space-6);
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.scope > svg {
  flex: none;
}
.scopeLabel {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.media {
  grid-area: media;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--cipher-size-control-lg);
  height: var(--cipher-size-control-lg);
}
.media > * {
  flex: none;
  max-width: 100%;
  max-height: 100%;
}
.media[data-dropped] {
  display: none;
}
.titleLine {
  grid-area: title;
  min-width: min(var(--cipher-size-text-min), 100%);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-8) var(--cipher-space-12);
}
/* The title flows as inline text so badges, such as the docs link, sit at the end of its last line instead of wrapping below it. */
.titleLine[data-flow="inline"] {
  display: block;
}
.titleLine[data-flow="inline"] > .title {
  display: inline;
}
.titleLine[data-flow="inline"] > .badges {
  min-height: var(--cipher-type-display-line-height);
  vertical-align: top;
}
/* A space rather than a margin, so the gap drops away when the badges wrap to a line of their own. */
.titleGap {
  display: none;
}
.titleLine[data-flow="inline"] > .titleGap {
  display: inline;
  word-spacing: calc(var(--cipher-space-12) - 0.25em);
}
.header[data-size="md"] .titleLine[data-flow="inline"] > .badges {
  min-height: var(--cipher-type-title-lg-line-height);
}
.title {
  min-width: 0;
  margin: 0;
  overflow-wrap: break-word;
  color: var(--cipher-ink);
  font-family: var(--cipher-type-display-font-family);
  font-size: var(--cipher-type-display-font-size);
  line-height: var(--cipher-type-display-line-height);
  font-weight: var(--cipher-type-display-font-weight);
  letter-spacing: var(--cipher-type-display-letter-spacing);
}
.header[data-size="md"] .title {
  font-family: var(--cipher-type-title-lg-font-family);
  font-size: var(--cipher-type-title-lg-font-size);
  line-height: var(--cipher-type-title-lg-line-height);
  font-weight: var(--cipher-type-title-lg-font-weight);
  letter-spacing: var(--cipher-type-title-lg-letter-spacing);
}
.mono {
  font-family: var(--cipher-font-mono);
  letter-spacing: 0;
}
.header[data-size="md"] .mono {
  font-family: var(--cipher-font-mono);
}
.badges {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-6);
}
.titleToggle {
  outline: none;
}
.title:has(> .titleToggle:focus-visible) {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.title[data-truncate] {
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  grid-area: description;
  margin: var(--cipher-space-10) 0 0;
  max-width: var(--cipher-size-measure-prose);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-body-lg-font-family);
  font-size: var(--cipher-type-body-lg-font-size);
  line-height: var(--cipher-type-body-lg-line-height);
  font-weight: var(--cipher-type-body-lg-font-weight);
  letter-spacing: var(--cipher-type-body-lg-letter-spacing);
}
.header[data-size="md"] .description {
  margin-top: var(--cipher-space-8);
}
.actions {
  grid-area: actions;
  display: flex;
  max-width: 100%;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-type-display-line-height);
}
.header[data-size="md"] .actions {
  min-height: var(--cipher-type-title-lg-line-height);
}
.moreInline {
  display: contents;
}
.moreMenu.moreMenu {
  display: none;
}
.tabs {
  margin-top: var(--cipher-space-24);
}
@container page-header (max-width: 40rem) {
  .moreInline {
    display: none;
  }
  .moreMenu.moreMenu {
    display: inline-flex;
  }
  .main {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "title"
      "description"
      "actions";
  }
  .main:has(> .media:not([data-dropped])) {
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas:
      "media title"
      "media description"
      "media actions";
  }
  .main:has(> .scope) {
    grid-template-areas:
      "scope"
      "title"
      "description"
      "actions";
  }
  .main:has(> .media:not([data-dropped])):has(> .scope) {
    grid-template-areas:
      "media scope"
      "media title"
      "media description"
      "media actions";
  }
  .title {
    --cipher-page-header-title-clamp: 2;
  }
  .titleLine:has(> .badges > [data-collapse]:only-child) {
    flex-wrap: nowrap;
  }
  .titleLine:has(> .badges > [data-slot="documentation-link"]:only-child) {
    flex-wrap: nowrap;
    align-items: flex-end;
  }
  .titleLine:has(> .badges > [data-collapse]:only-child) > .badges {
    display: contents;
  }
  .titleLine[data-flow="inline"]:has(> .badges > [data-collapse]:only-child) {
    display: flex;
  }
  .titleLine[data-flow="inline"]:has(> .badges > [data-collapse]:only-child) > .title {
    display: block;
  }
  .titleLine[data-flow="inline"]:has(> .badges > [data-collapse]:only-child) > .titleGap {
    display: none;
  }
  .title[data-clamped]:not([data-truncate], [data-expanded]) {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
  }
  .actions {
    justify-content: flex-start;
    margin-top: var(--cipher-space-16);
  }
  .actions
    [data-slot="button"]:has([data-button-icon]):not(
      :has(svg:not([data-button-icon], [data-slot="button-progress"]))
    ):has([data-slot="button-text"]) {
    width: var(--cipher-action-height);
    min-width: var(--cipher-action-height);
    padding-inline: 0;
  }
  .actions
    [data-slot="button"][data-size="default"]:has([data-button-icon]):not(
      :has(svg:not([data-button-icon], [data-slot="button-progress"]))
    ):has([data-slot="button-text"]) {
    --cipher-action-icon-size: var(--cipher-size-icon-sm);
  }
  .actions
    [data-slot="button"]:has([data-button-icon]):not(
      :has(svg:not([data-button-icon], [data-slot="button-progress"]))
    )
    [data-slot="button-text"] {
    display: block;
    position: absolute;
    width: 0;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}
